using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Evaluation;

public class EvaluationTests
{
    [Fact]
    public async Task AppStartsSuccessfully()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }

    [Fact]
    public async Task AppRespondsToRequests()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));

        // Verify the app host itself is running and responsive
        var resourceNotificationService = app.Services
            .GetRequiredService<ResourceNotificationService>();

        Assert.NotNull(resourceNotificationService);
    }
}

